//对于不同的进制之间转换, 都是从低位到高位的字符遍历, 需要的最高位前面不足位补什么字符就好了.
void transform(string &num, int a, int b)
{
	int sum = 0;
	int d = 1;
	for (int i = num.size() - 1; i >= 0; --i)
	{
		int cur = num[i] - '0' + d; //当前位
		d = cur / b;
		sum = sum + cur % b * d;
	}
	//输出
	if (sum == 0)
	{
		printf("0");
	}
	while (sum > 0)
	{
		int result = sum % b;
		sum /= b;
		if (result >= 0 && result < 10)
		{
			putchar('0' + result);
		} else
		{
			putchar('A' + result - 10);
		}
	}
}

